const getBookBeforeCustom=getBook;
getBook=function(id){if(id!==CUSTOM_BG_ID)return getBookBeforeCustom(id);const x=c(),b=x?.customBackground||x?.customBackgroundDraft||{};return {id,kind:'Antecedentes',name:'Customizado',abilities:(b.abilities||[0,1,2]).map(i=>AB_EN[i]),skills:(b.skills||[]).map(i=>SK_EN[i]).join(' and '),feat:b.featName||getBookBeforeCustom(b.feat)?.name||'',text:'Tool Proficiency: '+(b.tool||'Escolher ferramenta')+'\nEquipment: '+(b.kit==='gold'?'50 PO':getBookBeforeCustom(b.kit)?.name||'Escolher pacote'),page:0};};
let customBGStep=0,customBGContext='wizard';
function customBGDraft(){return c().customBackgroundDraft;}
function openCustomBackground(context='wizard'){customBGContext=context;const x=c();x.customBackgroundDraft=structuredClone(x.customBackground||{abilities:[],mode:'2+1',a:null,b:null,skills:[],feat:'',magicClass:'Wizard',tool:'',kit:'gold'});customBGStep=0;renderCustomBackground();document.querySelector('#custom-bg-dialog').showModal();}
