const CUSTOM_TOOLS=['Ferramentas de alquimista','Ferramentas de cervejeiro','Ferramentas de carpinteiro','Ferramentas de cartógrafo','Ferramentas de sapateiro','Utensílios de cozinheiro','Ferramentas de vidreiro','Ferramentas de joalheiro','Ferramentas de coureiro','Ferramentas de pedreiro','Suprimentos de pintor','Ferramentas de oleiro','Ferramentas de ferreiro','Ferramentas de funileiro','Ferramentas de tecelão','Ferramentas de entalhador','Suprimentos de calígrafo','Kit de disfarce','Kit de falsificação','Kit de herbalismo','Ferramentas de navegador','Kit de venenos','Ferramentas de ladrão','Dados','Baralho','Xadrez de dragão','Três dragões','Alaúde','Flauta','Lira','Tambor','Violino','Trompa','Gaita de foles','Dulcimer','Flauta de Pã','Xilofone'];
function customSelect(label,key,options,value){return `<label>${label}<select data-custom-key="${esc(key)}" aria-label="${esc(label)}" onchange="customBGDraft()['${key}']=this.value;save();${key==='feat'?'renderCustomBackground()':''}"><option value="">Escolher…</option>${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function renderCustomBackground(){const b=customBGDraft();if(!b)return;let body='';const titles=['Três atributos','Distribuição dos bônus','Talento de Origem','Duas perícias','Uma ferramenta','Equipamento inicial','Revisão'];if(customBGStep===0)body=`<p>Escolha três atributos diferentes.</p><div class="custom-bg-choices">${ATTR.map((n,i)=>`<label class="calc-option"><input type="checkbox" ${b.abilities.includes(i)?'checked':''} onchange="toggleCustomAbility(${i},this.checked)"><span>${n}</span></label>`).join('')}</div>`;
if(customBGStep===1)body=customSelect('Distribuição','mode',[['2+1','+2 em um atributo e +1 em outro'],['1+1+1','+1 nos três atributos']],b.mode)+`<p>Os valores finais não podem ultrapassar 20.</p><div id="custom-boost-targets">${customSelect('+2 em','a',b.abilities.map(i=>[i,ATTR[i]]),b.a)}${customSelect('+1 em','b',b.abilities.map(i=>[i,ATTR[i]]),b.b)}</div>`;
if(customBGStep===2){body=customSelect('Talento de Origem','feat',wentries('Talentos').filter(e=>/Origin/i.test(e.text.slice(0,100))).map(e=>[e.id,e.name]),b.feat);if(getBook(b.feat)?.name==='Magic Initiate')body+=customSelect('Lista de Iniciado em Magia','magicClass',[['Cleric','Clérigo'],['Druid','Druida'],['Wizard','Mago']],b.magicClass);}
if(customBGStep===3)body=`<p>Escolha duas perícias que combinem com a história do antecedente.</p>${[0,1].map(i=>customSelect('Perícia '+(i+1),'skill'+i,SKILLS.map(([n],i)=>[i,n]),b.skills[i])).join('')}`;
if(customBGStep===4)body=customSelect('Proficiência em ferramenta','tool',CUSTOM_TOOLS,b.tool);
if(customBGStep===5)body=customSelect('Equipamento','kit',[['gold','50 peças de ouro'],...wentries('Antecedentes').filter(e=>e.id!==CUSTOM_BG_ID).map(e=>[e.id,'Pacote de '+e.name])],b.kit)+`<p>Escolha um pacote de antecedente padrão ou 50 PO. As compras deste antecedente não incluem armas marciais nem armaduras médias ou pesadas.</p>`;
if(customBGStep===6)body=`<dl><dt>Atributos</dt><dd>${b.abilities.map(i=>ATTR[i]).join(', ')} · ${b.mode}</dd><dt>Talento</dt><dd>${esc(getBook(b.feat)?.name)}${getBook(b.feat)?.name==='Magic Initiate'?' · '+esc(b.magicClass):''}</dd><dt>Perícias</dt><dd>${b.skills.map(i=>SKILLS[i][0]).join(', ')}</dd><dt>Ferramenta</dt><dd>${esc(b.tool)}</dd><dt>Equipamento</dt><dd>${b.kit==='gold'?'50 PO':esc(getBook(b.kit)?.name)}</dd></dl>`;
document.querySelector('#custom-bg-dialog').innerHTML=`<div class="dialog-heading"><h2>Customizado · ${titles[customBGStep]}</h2><button aria-label="Fechar" onclick="document.querySelector('#custom-bg-dialog').close()">×</button></div><p class="eyebrow">ETAPA ${customBGStep+1} DE 7</p>${body}<p id="custom-bg-error" role="alert"></p><div class="actions"><button ${customBGStep===0?'disabled':''} onclick="customBGStep--;renderCustomBackground()">Voltar</button><button class="primary" onclick="nextCustomBackground()">${customBGStep===6?'Aplicar antecedente':'Próximo'}</button></div>`;
const mode=document.querySelector('#custom-bg-dialog select[data-custom-key="mode"]');if(mode){const apply=()=>document.querySelector('#custom-boost-targets').hidden=customBGDraft().mode==='1+1+1';mode.addEventListener('change',apply);apply();}enhanceSelects(document.querySelector('#custom-bg-dialog'));}
function toggleCustomAbility(i,checked){const b=customBGDraft();if(checked&&!b.abilities.includes(i)){if(b.abilities.length>=3){renderCustomBackground();return;}b.abilities.push(i);}else if(!checked)b.abilities=b.abilities.filter(n=>n!==i);save();}
function nextCustomBackground(){const b=customBGDraft();let error='';if(customBGStep===0){if(b.abilities.length!==3||new Set(b.abilities).size!==3)error='Escolha três atributos diferentes.';else{if(!b.abilities.includes(Number(b.a)))b.a=b.abilities[0];if(!b.abilities.includes(Number(b.b))||Number(b.b)===Number(b.a))b.b=b.abilities[1];}}
if(customBGStep===1&&b.mode==='2+1'&&(b.a===''||b.b===''||Number(b.a)===Number(b.b)||!b.abilities.includes(Number(b.a))||!b.abilities.includes(Number(b.b))))error='Escolha dois atributos diferentes dentre os três selecionados.';
if(customBGStep===2&&!wentries('Talentos').some(e=>e.id===b.feat&&/Origin/i.test(e.text.slice(0,100))))error='Escolha um Talento de Origem.';
if(customBGStep===3){const first=document.querySelector('#custom-bg-dialog select[data-custom-key="skill0"]')?.value,second=document.querySelector('#custom-bg-dialog select[data-custom-key="skill1"]')?.value;if(first===''||second===''||first===second)error='Escolha duas perícias diferentes.';else b.skills=[Number(first),Number(second)];}
if(customBGStep===4&&!CUSTOM_TOOLS.includes(b.tool))error='Escolha uma ferramenta.';
if(customBGStep===5&&b.kit!=='gold'&&!wentries('Antecedentes').some(e=>e.id===b.kit&&e.id!==CUSTOM_BG_ID))error='Escolha 50 PO ou um pacote padrão.';
if(error){document.querySelector('#custom-bg-error').textContent=error;return;}if(customBGStep<6){customBGStep++;save();renderCustomBackground();return;}
b.a=Number(b.a);b.b=Number(b.b);b.complete=true;b.featName=getBook(b.feat).name+(getBook(b.feat).name==='Magic Initiate'?' ('+b.magicClass+')':'');if(customBGContext==='existing'){const error=customExistingError(b);if(error){document.querySelector('#custom-bg-error').textContent=error;return;}c().customBackground=structuredClone(b);applyCustomExisting(b);save();render();document.querySelector('#custom-bg-dialog').close();return;}c().customBackground=structuredClone(b);const d=wd();d.background=CUSTOM_BG_ID;d.boostMode=b.mode;d.a=b.a;d.b=b.b;d.bgKit=b.kit==='gold'?'gold':'A';wapply();save();render();wrender();document.querySelector('#custom-bg-dialog').close();}
