function historyView(){const x=c();if(!x.historyFields)x.historyFields={story:x.bio||'',appearance:'',traits:'',ideals:'',bonds:'',flaws:'',journal:x.notes||''};return `<section class="card history-card"><h3>História</h3><div class="history-fields">${[['story','História'],['appearance','Aparência'],['traits','Traços de Personalidade'],['ideals','Ideais'],['bonds','Vínculos'],['flaws','Falhas']].map(([key,label])=>`<label class="history-field history-${key}"><span>${label}</span><textarea aria-label="${label}" oninput="c().historyFields['${key}']=this.value;${key==='story'?"c().bio=this.value;":''}save()">${esc(x.historyFields[key]||'')}</textarea></label>`).join('')}${x.historyFields.journal?`<details class="legacy-journal"><summary>Anotações anteriores</summary><textarea aria-label="Anotações anteriores" oninput="c().historyFields.journal=this.value;c().notes=this.value;save()">${esc(x.historyFields.journal)}</textarea></details>`:''}</div></section>`;}
function proficiencySummary(){const x=c(),d=x.creationWizard||{},e=d.extra||{},s=selections(),bg=getBook(s.background)||wentries('Antecedentes').find(b=>b.name===x.background),tools=new Set(),languages=new Set(['Comum',...(x.species==='Kobold'?['language0']:['language0','language1']).map(k=>e[k]).filter(Boolean)]),weapons=new Set(),armor=new Set();
if(bg?.id===CUSTOM_BG_ID&&x.customBackground?.tool)tools.add(x.customBackground.tool);else if(bg){const raw=bg.text.match(/Tool Proficiency:\s*([\s\S]*?)\nEquipment:/i)?.[1]?.replace(/\s+/g,' ');if(raw&&!/^Choose/i.test(raw))tools.add(raw);}
for(const key of ['bgTool','bgInstrument','gaming','tool','instrument0','instrument1','instrument2','musician0','musician1','musician2'])if(e[key])tools.add(e[key]);
const classes=x.classes||[];for(const [i,p]of classes.entries()){const n=p.name;if(['Bárbaro','Guerreiro','Paladino','Patrulheiro'].includes(n))weapons.add('Simples e marciais');else if(i===0)weapons.add(n==='Ladino'?'Simples; marciais com Acuidade ou Leve':n==='Monge'?'Simples; marciais Leves':'Simples');
if(['Bárbaro','Guerreiro','Paladino','Patrulheiro','Clérigo'].includes(n)){armor.add('Leves');armor.add('Médias');armor.add('Escudos');if(i===0&&['Guerreiro','Paladino'].includes(n))armor.add('Pesadas');}else if(['Bardo','Ladino','Bruxo'].includes(n))armor.add('Leves');else if(n==='Druida'){armor.add('Leves');armor.add('Escudos');}
if(n==='Druida'){languages.add('Druídico');tools.add('Kit de herbalismo');}if(n==='Ladino'){languages.add('Gíria de Ladrões');if(i===0)tools.add('Ferramentas de ladrão');}}
if(e.order==='Protetor'){weapons.add('Simples e marciais');armor.add('Pesadas');}if(e.order==='Guardião'){weapons.add('Simples e marciais');armor.add('Médias');}
if(weapons.has('Simples e marciais')){weapons.clear();weapons.add('Simples e marciais');}
return `<section class="card proficiencies-summary"><h3>Proficiências e Idiomas</h3><dl>${[['Ferramentas',[...tools].join(', ')||'Nenhuma selecionada'],['Idiomas',[...languages].join(', ')],['Armas',[...weapons].join(', ')||'Nenhuma'],['Armaduras',[...armor].join(', ')||'Nenhuma']].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></section>`;}
const essentialsBeforeCombined=essentialsView;essentialsView=function(){const box=document.createElement('div');box.innerHTML=essentialsBeforeCombined();box.querySelector('h3').textContent='Essenciais e Recursos';const resources=document.createElement('div');resources.innerHTML=resourcesView();const card=resources.querySelector('section');card?.querySelector('h2')?.remove();if(card){const nested=document.createElement('div');nested.className='essential-resources';nested.innerHTML=card.innerHTML;box.querySelector('section').appendChild(nested);}return box.innerHTML;};
overview=function(){const box=document.createElement('div');box.innerHTML=integratedOverview();const layout=box.querySelector('.overview-layout');let sibling=layout?.nextElementSibling;if(sibling?.querySelector('h2')?.textContent==='Recursos')sibling.remove();const progress=box.querySelector('.progression-details');progress?.remove();return box.innerHTML+proficiencySummary()+historyView()+(progress?.outerHTML||'');};
// Háptico e valores locais: as luzes e o retrato não são recriados.
hpTouchFeedback=function(){try{if(typeof CodiceAndroid!=='undefined'&&CodiceAndroid.haptic)CodiceAndroid.haptic();else navigator.vibrate?.(12);}catch{}};
function updateHPDisplay(){const x=c(),v=vitalityParts(x),header=document.querySelector('#session-header');if(!header)return;const heart=header.querySelector('.ruby-crest');if(heart){heart.style.setProperty('--hp-danger',Math.max(0,Math.min(1,1-x.hp/Math.max(1,x.maxhp))));heart.classList.toggle('hp-full',x.hp>=x.maxhp);heart.classList.toggle('hp-protected',x.temp>0);heart.querySelector('.vital-number b').textContent=x.hp;const waves=heart.querySelector('.heart-blue-sparks');if(x.temp>0&&!waves)heart.insertAdjacentHTML('beforeend','<span class="heart-blue-sparks" aria-hidden="true"></span>');else if(!x.temp)waves?.remove();}
const vitality=header.querySelector('.vitality');if(vitality){const red=vitality.querySelector('.vitality-base');red.style.width=v.red+'%';red.setAttribute('aria-valuenow',v.hp);red.setAttribute('aria-valuemax',v.max);red.setAttribute('aria-valuetext',`${v.hp} de ${v.max} pontos de vida`);let blue=vitality.querySelector('.vitality-temp');if(v.temp){if(!blue){vitality.querySelector('.vitality-track').insertAdjacentHTML('beforeend',`<div class="vitality-temp" role="meter" aria-label="PV temporários">${liquidBubbles('blue')}</div>`);blue=vitality.querySelector('.vitality-temp');}blue.style.width=v.blue+'%';blue.setAttribute('aria-valuemin','0');blue.setAttribute('aria-valuemax',v.temp);blue.setAttribute('aria-valuenow',v.temp);}else blue?.remove();const legend=vitality.querySelector('.vitality-legend');if(legend)legend.innerHTML=`<span><i class="red-dot"></i> ${v.hp} / ${v.max} PV</span><span><i class="blue-dot"></i> ${v.temp} temporários</span>`;}const temp=header.querySelector('.temp-hp-controls>span b');if(temp)temp.textContent=x.temp;}
crestHPChange=function(kind,direction){const x=c();if(kind==='temp')x.temp=Math.max(0,Math.min(1000000,(Number(x.temp)||0)+direction));else if(direction>0)x.hp=Math.min(x.maxhp,x.hp+1);else{const absorb=Math.min(Math.max(0,x.temp),1);x.temp-=absorb;x.hp=Math.max(0,x.hp-1+absorb);}save();updateHPDisplay();hpTouchFeedback();};
openRestDialog=function(){openPlayDialog('Descanso Longo',`<p>Após ao menos 8 horas de descanso, você recupera todos os PV e Dados de Vida, espaços de magia e Magia de Pacto. Os recursos de descanso longo são restaurados, a concentração é encerrada e as salvaguardas contra a morte são zeradas.</p><p>Recursos personalizados seguem o descanso configurado. Efeitos e condições não automatizados devem ser conferidos na mesa.</p><button class="primary" onclick="rest();document.querySelector('#play-dialog').close()">Realizar Descanso Longo</button>`);};
function openShortRestDialog(){const x=c();openPlayDialog('Descanso Curto',`<p>Após ao menos 1 hora de descanso, você recupera Magia de Pacto e recursos de descanso curto. Canalizar Divindade, Forma Selvagem e Retomar o Fôlego recuperam 1 uso quando disponíveis. Fúria recupera 1 uso.</p><p>Você pode gastar Dados de Vida abaixo para recuperar PV, somando Constituição a cada dado. Descanso curto não recupera os Dados de Vida gastos.</p>${x.classes.map(p=>{const used=x.hitDiceUsed[p.name]||0;return `<button class="hit-die-choice" ${used>=p.level?'disabled':''} onclick="spendDie('${p.name}')">Rolar d${HIT_DIE[p.name]} · ${esc(p.name)} · ${p.level-used}/${p.level} restantes</button>`;}).join('')}<button class="primary" onclick="shortRest();document.querySelector('#play-dialog').close()">Realizar Descanso Curto</button>`);}
const headerBeforeRest41=quickHeader;quickHeader=function(){const x=c(),counts=x.classes.map(p=>`${Math.max(0,p.level-(x.hitDiceUsed[p.name]||0))}/${p.level} d${HIT_DIE[p.name]}`).join(' + ');return headerBeforeRest41().replace(/<button class="rest-dice-count"[\s\S]*?<\/button>/,`<button class="rest-dice-count short-rest-button" onclick="openShortRestDialog()" aria-label="Descanso Curto"><span class="rest-dice-value">${counts}</span><span class="rest-label">Descanso Curto</span></button>`);};
// Mantém o mesmo elemento no DOM e desloca somente uma textura periódica.
seedEpicWind=function(hero){const layer=hero?.querySelector('.class-wind');if(!layer||layer.dataset.smooth41)return;layer.dataset.smooth41='true';layer.innerHTML=Array.from({length:6},(_,i)=>`<span class="wind-flow" style="top:${10+i*15}%;--flow-time:${18+i*3}s;--flow-delay:-${i*4.7}s"></span>`).join('');};
const portraitBeforeRestore41=renderPortrait;renderPortrait=function(){portraitBeforeRestore41();const hero=document.querySelector('.hero'),ci=CLASSES.indexOf(c()?.classes?.[0]?.name||c()?.cls);if(ci>=0){hero.style.setProperty('background-image',`linear-gradient(90deg,#102331bf,#10233130 48%,#10233110),url('class-scene-${ci}.webp')`,'important');hero.style.setProperty('background-size','100% 100%,cover','important');hero.style.backgroundPosition='center,68% 35%';}seedEpicWind(hero);};
