function customExistingBoosts(b){const boosts=Array(6).fill(0);if(b.mode==='1+1+1')for(const i of b.abilities)boosts[i]=1;else{boosts[b.a]=2;boosts[b.b]=1;}return boosts;}
function customExistingError(b){const boosts=customExistingBoosts(b),s=selections();return c().attrs.some((value,i)=>value-(s.appliedBoosts?.[i]||0)+boosts[i]>20)?'Essa distribuição ultrapassa 20. Volte e escolha outros atributos.':'';}
function applyCustomExisting(b){const x=c(),s=selections(),boosts=customExistingBoosts(b);x.attrs=x.attrs.map((value,i)=>value-(s.appliedBoosts?.[i]||0)+boosts[i]);s.appliedBoosts=boosts;s.background=CUSTOM_BG_ID;x.background='Customizado';for(const old of s.originSkills||[])if(x.skills[old.i]===1)x.skills[old.i]=old.before;s.originSkills=b.skills.map(i=>({i,before:x.skills[i]||0}));for(const i of b.skills)x.skills[i]=Math.max(1,x.skills[i]||0);s.feats=s.feats.filter(id=>id!==s.customOriginFeat);s.customOriginFeat=b.feat;s.feats=[...new Set(s.feats.concat(b.feat))];s.originFeat=b.featName;x.calc.tough=s.feats.some(id=>getBook(id)?.name==='Tough');const gold=customKitGold();x.money=Number(x.money||0)-(s.customBGMoney||0)+gold;s.customBGMoney=gold;const kit=b.kit==='gold'?'50 PO':wbgEquipment(getBook(CUSTOM_BG_ID));x.equipment=x.equipment.replace(/\[Antecedente Customizado\][\s\S]*?\[\/Antecedente Customizado\]/g,'').trim()+'\n[Antecedente Customizado]\n'+kit+'\n[/Antecedente Customizado]';recalc(x);}
document.addEventListener('click',event=>{const button=event.target.closest?.('button');if(button&&!button.matches('.hp-minus,.hp-plus,.temp-hp-controls .temp-hp-add'))hpTouchFeedback();},true);
