const SHORT_ATTR=['FOR','DES','CON','INT','SAB','CAR'];
function select45(label,id,options,value){return `<label>${label}<select id="${id}" aria-label="${esc(label)}">${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function input45(label,id,value,type='text'){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value??'')}"></label>`;}
function check45(label,id,checked){return `<label class="calc-option"><input id="${id}" type="checkbox" ${checked?'checked':''}><span>${label}</span></label>`;}
function attrOptions45(){return [['none','Nenhum'],...ATTR.map((a,i)=>[i,a]),['spell','Atributo de conjuração']];}
function attackAttribute45(value){return value==='none'?0:mod(c().attrs[value==='spell'?c().spellAttr:Number(value)]);}
function parseDice45(expression){const clean=String(expression||'').replace(/\s+/g,'').toLowerCase();if(!clean)return {dice:[],flat:0};if(!/^[+-]?(?:(?:\d{0,2}d(?:4|6|8|10|12|20|100))|\d+)(?:[+-](?:(?:\d{0,2}d(?:4|6|8|10|12|20|100))|\d+))*$/.test(clean))throw Error('Use dados e somas, como 2d6 + 1d4 + 3.');let flat=0,dice=[];for(const term of clean.match(/[+-]?[^+-]+/g)){if(term.includes('d')){if(term.startsWith('-'))throw Error('Dados negativos não são aceitos.');const[count,sides]=term.replace(/^\+/,'').split('d');const n=count===''?1:Number(count);if(n<1||n>30)throw Error('Use de 1 a 30 dados por termo.');dice.push(...Array(n).fill(Number(sides)));}else flat+=Number(term);}if(dice.length>60)throw Error('Limite de 60 dados no cálculo; até 12 aparecem na animação.');return {dice,flat};}
