saveManualAttack=function(i){const val=id=>document.getElementById(id).value,num=id=>Number(val(id))||0,checked=id=>document.getElementById(id).checked;try{const name=val('ma-name').trim();if(!name)throw Error('Informe o nome do ataque.');const damage=n=>{const d={enabled:checked(`ma-d${n}-enabled`),formula:val(`ma-d${n}-formula`),attr:val(`ma-d${n}-attr`),bonus:num(`ma-d${n}-bonus`),type:val(`ma-d${n}-type`),critical:val(`ma-d${n}-critical`)};if(d.enabled){parseDice45(d.formula);if(d.critical)parseDice45(d.critical);}return d;};const form45={attack:checked('ma-attack'),attr:val('ma-attr'),prof:checked('ma-prof'),attackBonus:num('ma-attack-bonus'),range:val('ma-range'),magic:num('ma-magic'),crit:Math.max(1,Math.min(20,num('ma-crit')||20)),magicDamage:checked('ma-magic-damage'),damage:damage(1),damage2:damage(2),save:checked('ma-save'),saveAttr:num('ma-save-attr'),dcMode:val('ma-dc-mode'),dc:num('ma-dc'),dcAttr:val('ma-dc-attr'),dcBonus:num('ma-dc-bonus'),effect:val('ma-effect'),ammo:val('ma-ammo')};const a={...(c().attacks[i]||{}),id:c().attacks[i]?.id||crypto.randomUUID(),name,mastery:val('ma-note'),form45};const n=customNumbers45(a);a.bonus=n.bonus;a.damage=n.damage;if(i<0)c().attacks.push(a);else c().attacks[i]=a;save();render();document.querySelector('#play-dialog').close();}catch(e){document.querySelector('#ma-error').textContent=e.message;}};
