const levelErrorBefore45=levelUpError;levelUpError=function(x,d){const error=levelErrorBefore45(x,d);if(error)return error;if(d.asi==='feat'){const feat=getBook(d.feat),invalid=featError45(feat,x);if(invalid)return invalid;const boost=featBoost45(feat);if(boost){if(!Number.isInteger(d.featAttr)||!boost.allowed.includes(d.featAttr))return 'Escolha o atributo do talento.';const amount=boost.asi&&d.featMode==='2'?2:1;if(x.attrs[d.featAttr]+amount>boost.cap)return 'O aumento do talento ultrapassa o limite.';if(boost.asi&&d.featMode==='1+1'&&(!Number.isInteger(d.featAttr2)||d.featAttr2===d.featAttr||x.attrs[d.featAttr2]>=boost.cap))return 'Escolha outro atributo para o segundo +1.';}}return '';};
function grantsFor45(cls,n,subclass,featName='',multiclass=false){const all=SKILLS.map((_,i)=>i),tasks=[],add=(name,mode,count,options=all)=>tasks.push({name,mode,count,options});if(cls==='Bárbaro'&&n===3)add('Conhecimento Primal','prof',1,W_CLASS[cls].skills);if(cls==='Mago'&&n===2)add('Estudioso','expert',1,[1,6,9,11,12,16]);if(cls==='Bardo'&&[2,9].includes(n))add('Especialização de Bardo','expert',2);if(cls==='Ladino'&&[1,6].includes(n))add('Especialização de Ladino','expert',2);if(cls==='Patrulheiro'&&n===2)add('Explorador Habilidoso','expert',1);if(cls==='Patrulheiro'&&n===9)add('Especialização de Patrulheiro','expert',2);if(multiclass&&n===1&&['Bardo','Ladino','Patrulheiro'].includes(cls))tasks.unshift({name:'Perícia de multiclasse · '+cls,mode:'prof',count:1,options:W_CLASS[cls].skills});if(n===3&&/College of Lore/i.test(subclass))add('Proficiências adicionais · Conhecimento','prof',3);if(n===3&&/Battle Master/i.test(subclass))add('Estudante da Guerra','prof',1,W_CLASS['Guerreiro'].skills);if(n===3&&/Warrior of Mercy/i.test(subclass))tasks.push({name:'Instrumentos da Misericórdia',mode:'fixed',options:[8,11],count:2,tools:['Kit de herbalismo']});if(n===3&&/Fey Wanderer/i.test(subclass))add('Encanto Sobrenatural','prof',1,[3,4,14]);if(featName==='Skilled')add('Talento Habilidoso','skillOrTool',3);if(featName==='Skill Expert'){add('Perito em Perícias · proficiência','prof',1);add('Perito em Perícias · especialização','expert',1);}if(featName==='Keen Mind')add('Mente Aguçada','upgrade',1,[1,6,9,12,16]);if(featName==='Observant')add('Observador','upgrade',1,[8,9,13]);if(featName==='Boon of Skill'){tasks.push({name:'Dádiva de Perícias',mode:'fixed',options:all,count:18});add('Dádiva de Perícias · especialização','expert',1);}return tasks;}
function nextGrant45(){const d=levelDraft,t=d.grantTasks[0];if(!t){d.grantsReady=true;evoDialog45.close();return commitLevelUp();}if(t.mode==='fixed'){for(const i of t.options)d.skillWorking[i]=Math.max(1,d.skillWorking[i]||0);d.toolWorking.push(...(t.tools||[]));d.grantTasks.shift();return nextGrant45();}const options=t.options.filter(i=>t.mode==='expert'?d.skillWorking[i]===1:t.mode==='upgrade'?d.skillWorking[i]<2:!d.skillWorking[i]).map(i=>['skill:'+i,SKILLS[i][0]]);if(t.mode==='skillOrTool')for(const name of CUSTOM_TOOLS)if(!d.toolWorking.includes(name))options.push(['tool:'+name,name]);if(!options.length){d.grantTasks.shift();return nextGrant45();}evoDialog45.innerHTML=`<h2>${esc(t.name)}</h2><p>${t.mode==='expert'?'Escolha uma perícia em que já é Proficiente, sem Especialização.':t.mode==='upgrade'?'Sem treinamento: concede Proficiência. Se já é Proficiente: concede Especialização.':'Escolha uma proficiência nova.'} ${t.count} escolha(s) restante(s).</p>${select45('Proficiência adquirida','evo-grant',options,options[0][0])}<button class="primary" onclick="chooseGrant45()">Confirmar escolha</button>`;if(!evoDialog45.open)evoDialog45.showModal();enhanceSelects(evoDialog45);}
function chooseGrant45(){const d=levelDraft;if(!d?.grantTasks?.length||d.committed)return;const t=d.grantTasks[0],value=document.querySelector('#evo-grant').value;if(value.startsWith('tool:'))d.toolWorking.push(value.slice(5));else{const i=Number(value.slice(6));if(!t.options.includes(i))return;const before=d.skillWorking[i]||0;if(t.mode==='expert'&&before!==1)return;if(t.mode==='prof'&&before)return;d.skillWorking[i]=t.mode==='expert'||(t.mode==='upgrade'&&before===1)?2:1;}if(--t.count<=0)d.grantTasks.shift();nextGrant45();}
const commitBefore45=commitLevelUp;commitLevelUp=function(){const x=c(),d=levelDraft;if(!d||d.committed)return;const error=levelUpError(x,d);if(error)return toast(error);if(!d.grantsReady){const n=nextClassLevel(d.cls),subclass=getBook(d.subclass||selections().subclasses[d.cls])?.name||'',feat=d.asi==='feat'?getBook(d.feat):null;d.skillWorking=Object.fromEntries(SKILLS.map((_,i)=>[i,x.skills[i]||0]));d.toolWorking=[...(playState().grantedTools||[])];d.grantTasks=grantsFor45(d.cls,n,subclass,feat?.name,!x.classes.some(p=>p.name===d.cls));if(d.grantTasks.length)return nextGrant45();d.grantsReady=true;}
const previousLevel=x.level;commitBefore45();if(x.level!==previousLevel+1)return;d.committed=true;if(d.skillWorking)x.skills={...x.skills,...d.skillWorking};playState().grantedTools=[...new Set(d.toolWorking||[])];if(d.asi==='feat'){const feat=getBook(d.feat),boost=featBoost45(feat);selections().feats=[...new Set(selections().feats.concat(feat.id))];if(boost){x.attrs[d.featAttr]+=boost.asi&&d.featMode==='2'?2:1;if(boost.asi&&d.featMode==='1+1')x.attrs[d.featAttr2]++;}if(feat.name==='Tough')x.calc.tough=true;if(feat.name==='Resilient'&&!x.saves.includes(d.featAttr))x.saves.push(d.featAttr);if(feat.name==='Chef')playState().grantedTools.push('Utensílios de cozinheiro');}recalc(x);save();render();toast('Evolução e escolhas aplicadas à ficha.');};
const profSummaryBefore45=proficiencySummary;proficiencySummary=function(){const box=document.createElement('div');box.innerHTML=profSummaryBefore45();const dd=box.querySelectorAll('dd'),tools=playState().grantedTools||[];if(tools.length)dd[0].textContent=[dd[0].textContent==='Nenhuma selecionada'?'':dd[0].textContent,...tools].filter(Boolean).join(', ');const feats=selections().feats.map(getBook).filter(Boolean).map(e=>e.name);if(feats.includes('Martial Weapon Training'))dd[2].textContent='Simples e marciais';if(feats.includes('Lightly Armored'))dd[3].textContent+=' · Leves e Escudos';if(feats.includes('Moderately Armored'))dd[3].textContent+=' · Médias';if(feats.includes('Heavily Armored'))dd[3].textContent+=' · Pesadas';if(c().calc.acMode==='tortle')dd[3].textContent='Defesa Tortle · sem armaduras; Escudo permitido';return box.innerHTML;};
