const inventoryEquipBefore45=inventoryEquip;inventoryEquip=function(id){const item=playState().inventory.find(e=>e.id===id);if(item&&!item.equipped&&c().calc.acMode==='tortle'&&isArmorEquipment45(item))return toast('Defesa Tortle impede o uso de armaduras. Escudo é permitido.');return inventoryEquipBefore45(id);};
function alignHeroControls45(){const hero=document.querySelector('.hero'),band=document.querySelector('#portrait-band');if(!hero||!band||band.hidden)return;band.style.transform='';const h=hero.getBoundingClientRect(),b=band.getBoundingClientRect();if(!h.height||!b.height)return;const target=h.top+h.height*.75,center=b.top+b.height/2,shift=Math.min(target-center,h.bottom-10-b.bottom);band.style.transform=`translateY(${shift}px)`;}
var heroAlignmentFrame562=0;function scheduleHeroAlignment562(){if(heroAlignmentFrame562||!window.requestAnimationFrame)return;heroAlignmentFrame562=requestAnimationFrame(()=>{heroAlignmentFrame562=0;if(!document.hidden)alignHeroControls45();});}const finalRenderBefore45=render;render=function(){finalRenderBefore45();scheduleHeroAlignment562();};window.addEventListener('resize',scheduleHeroAlignment562);render();

