function isArmorEquipment45(item){const name=normBook(item.name);if(/shield|escudo/.test(name))return false;return /\b(armor|armour|mail|plate|halfplate|leather|hide|breastplate|splint|padded|studded|gibao|armadura|cota|camisao|brunea|couro|talas|placas)\b|chain\s*(shirt|mail)|half\s*plate|scale\s*mail|ring\s*mail/i.test(name);}

// 4.6: per-character roll modifiers and persistent mixed attack ordering.
const ROLL_GROUPS46={skill:'Perícias',attack:'Ataques',save:'Salvaguardas'};
function globalMods46(){const p=playState();p.globalRollModifiers??={};for(const key of Object.keys(ROLL_GROUPS46)){p.globalRollModifiers[key]??={enabled:false,bonus:0};}return p.globalRollModifiers;}
function setGlobalMod46(key,field,value){if(!ROLL_GROUPS46[key])return;const m=globalMods46()[key];if(field==='enabled')m.enabled=!!value;else{const n=Number(value);if(!Number.isFinite(n)||!Number.isInteger(n))return toast('Informe um modificador inteiro.');m.bonus=n;}save();render();}
function chooseGlobalMod46(key,value){if(value!=='custom')return setGlobalMod46(key,'bonus',value);openPlayDialog('Modificador · '+ROLL_GROUPS46[key],`<label>Bônus ou penalidade<input id="global-mod-value" type="number" step="1" value="${globalMods46()[key].bonus}"></label><button class="primary" onclick="const v=document.querySelector('#global-mod-value').value;if(v.trim()&&Number.isInteger(Number(v))){setGlobalMod46('${key}','bonus',v);document.querySelector('#play-dialog').close();}">Aplicar</button>`);}
function globalModsView46(){const mods=globalMods46();return `<div class="global-roll-modifiers"><h4>Modificadores de rolagem</h4>${Object.entries(ROLL_GROUPS46).map(([key,name])=>{const m=mods[key],values=Array.from({length:21},(_,i)=>i-10);if(!values.includes(m.bonus))values.push(m.bonus);return `<div class="global-mod-row"><label><input type="checkbox" aria-label="Ativar modificador de ${name}" ${m.enabled?'checked':''} onchange="setGlobalMod46('${key}','enabled',this.checked)">${name}</label><label class="global-mod-select"><span class="sr-only">Bônus de ${name}</span><select aria-label="Bônus de ${name}" onchange="chooseGlobalMod46('${key}',this.value)">${values.map(n=>`<option value="${n}" ${m.bonus===n?'selected':''}>${signed(n)}</option>`).join('')}<option value="custom">Outro valor…</option></select></label></div>`;}).join('')}<small>Aplicados enquanto marcados. Valores negativos são penalidades.</small></div>`;}
const essentialsBefore46=essentialsView;essentialsView=function(){const box=document.createElement('div');box.innerHTML=essentialsBefore46();box.querySelector('section')?.insertAdjacentHTML('beforeend',globalModsView46());return box.innerHTML;};
const requestBefore46=requestDice;requestDice=function(request){const m=ROLL_GROUPS46[request.rollKind]?globalMods46()[request.rollKind]:null;if(m?.enabled&&!request.globalModApplied){request={...request,bonus:(Number(request.bonus)||0)+m.bonus,globalModApplied:true,note:[request.note,`Modificador global de ${ROLL_GROUPS46[request.rollKind]}: ${signed(m.bonus)}`].filter(Boolean).join(' · ')};}return requestBefore46(request);};
function removeTextPanel46(html,key){const box=document.createElement('div');box.innerHTML=html;box.querySelector(`textarea[oninput*="${key}"]`)?.closest('section.card')?.remove();return box.innerHTML;}
const magicBefore46=magic;magic=function(){return removeTextPanel46(magicBefore46(),'spellnotes');};
const combatBefore46=combat;combat=function(){return removeTextPanel46(combatBefore46(),'equipment');};
function attackEntries46(){return [...playState().weapons.filter(e=>weaponNumbers(c(),e)).map(e=>({key:'weapon:'+e.id,name:weaponNumbers(c(),e).w.name})),...c().attacks.map(a=>({key:'manual:'+a.id,name:a.name}))];}
function attackOrder46(){const p=playState(),keys=attackEntries46().map(e=>e.key);p.attackOrder=[...new Set([...(p.attackOrder||[]).filter(k=>keys.includes(k)),...keys])];return p.attackOrder;}
const weaponsBefore46=sheetWeapons;sheetWeapons=function(){const box=document.createElement('div');box.innerHTML=weaponsBefore46();const entries=attackEntries46(),rows=[...box.querySelectorAll('.attack-line')],map=new Map();rows.forEach((row,i)=>{if(entries[i]){row.dataset.attackKey=entries[i].key;map.set(entries[i].key,row);}});const add=box.querySelector('.attack-add');for(const key of attackOrder46())if(map.has(key))add.before(map.get(key));return box.innerHTML;};
function manageAttack46(key){const entry=attackEntries46().find(e=>e.key===key);if(!entry)return;const order=attackOrder46(),i=order.indexOf(key);openPlayDialog('Organizar · '+entry.name,`<p>${esc(entry.name)}</p><div class="attack-order-actions"><button ${i===0?'disabled':''} onclick="moveAttack46('${key}',${i-1})">↑ Subir</button><button ${i===order.length-1?'disabled':''} onclick="moveAttack46('${key}',${i+1})">↓ Descer</button></div><label>Posição na lista<select aria-label="Posição na lista" onchange="moveAttack46('${key}',Number(this.value))">${order.map((_,n)=>`<option value="${n}" ${n===i?'selected':''}>${n+1}</option>`).join('')}</select></label><button class="danger" onclick="confirmDeleteAttack46('${key}')">Excluir arma ou ataque</button>`);}
function moveAttack46(key,index){const order=attackOrder46(),from=order.indexOf(key);if(from<0||index<0||index>=order.length)return;order.splice(from,1);order.splice(index,0,key);save();render();manageAttack46(key);}
function confirmDeleteAttack46(key){const e=attackEntries46().find(e=>e.key===key);if(!e)return;openPlayDialog('Excluir arma ou ataque',`<p>Excluir <strong>${esc(e.name)}</strong> desta ficha?</p><button class="danger" onclick="deleteAttack46('${key}')">Excluir este ataque</button><button onclick="manageAttack46('${key}')">Cancelar</button>`);}
function deleteAttack46(key){const [kind,id]=key.split(':'),p=playState();if(kind==='weapon')p.weapons=p.weapons.filter(e=>e.id!==id);else if(kind==='manual')c().attacks=c().attacks.filter(e=>e.id!==id);else return;if(p.attackMedia)delete p.attackMedia[key];p.attackOrder=(p.attackOrder||[]).filter(k=>k!==key);save();render();document.querySelector('#play-dialog').close();}
(()=>{let hold=null,timer=0,suppress=null;const cancel=()=>{clearTimeout(timer);hold=null;};document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const row=e.target.closest('.attack-line[data-attack-key]');if(!row||e.target.closest('input,.attack-media-tools'))return;cancel();hold={row,key:row.dataset.attackKey,x:e.clientX,y:e.clientY};timer=setTimeout(()=>{if(!hold)return;suppress={row:hold.row,until:Date.now()+1000};const key=hold.key;cancel();if(typeof haptic==='function')haptic();manageAttack46(key);},650);});document.addEventListener('pointermove',e=>{if(hold&&Math.hypot(e.clientX-hold.x,e.clientY-hold.y)>12)cancel();});window.addEventListener('pointerup',cancel);window.addEventListener('pointercancel',cancel);window.addEventListener('blur',cancel);document.addEventListener('click',e=>{if(suppress&&Date.now()<suppress.until&&suppress.row.contains(e.target)){e.preventDefault();e.stopImmediatePropagation();suppress=null;}},true);})();
